cssCode:
.ripple-btn {
  position: relative; overflow: hidden; padding: 18px 50px;
  background: #1a1a2e; color: #fff; border: 1px solid #333;
  border-radius: 40px; font-size: 18px; font-weight: bold;
  font-family: sans-serif; cursor: pointer;
  box-shadow: 0 10px 20px rgba(0,0,0,0.5);
  transition: transform 0.2s;
}
.ripple-btn:active { transform: scale(0.95); }
.ripple-effect {
  position: absolute; border-radius: 50%;
  background: rgba(108, 99, 255, 0.6);
  transform: translate(-50%, -50%) scale(0);
  animation: rippleAnim 0.6s linear; pointer-events: none;
}
@keyframes rippleAnim {
  to { transform: translate(-50%, -50%) scale(4); opacity: 0; }
}

jsCode:
const c = document.getElementById('container');
c.style.cssText = 'width:100%;height:100%;display:flex;align-items:center;justify-content:center;background:transparent;';

const btn = document.createElement('button');
btn.className = 'ripple-btn';
btn.innerText = 'TOUCH ME';
c.appendChild(btn);

btn.addEventListener('pointerdown', (e) => {
  const rect = btn.getBoundingClientRect();
  const x = e.clientX - rect.left;
  const y = e.clientY - rect.top;

  const ripple = document.createElement('span');
  ripple.className = 'ripple-effect';
  ripple.style.left = `${x}px`;
  ripple.style.top = `${y}px`;

  // બટનની સાઇઝ મુજબ રિપલ સેટ કરવું
  const size = Math.max(rect.width, rect.height);
  ripple.style.width = `${size}px`;
  ripple.style.height = `${size}px`;

  btn.appendChild(ripple);
  setTimeout(() => ripple.remove(), 600);
});
